def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def tag(x,y,t,c='soft'):return R(x-15,y-10,30,20,c,5)+T(x,y+4,t,'t-s')
def v3(x,y,s=8):return f'<polygon points="{x-s},{y-s*.8} {x},{y} {x-s},{y+s*.8}" class="bx"/><polygon points="{x+s},{y-s*.8} {x},{y} {x+s},{y+s*.8}" class="bx"/><polygon points="{x-s*.8},{y+s} {x},{y} {x+s*.8},{y+s}" class="bx"/>'
def v2(x,y,s=7):return f'<polygon points="{x-s},{y-s} {x},{y} {x-s},{y+s}" class="bx"/><polygon points="{x+s},{y-s} {x},{y} {x+s},{y+s}" class="bx"/>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'

# ---- numbers (recomputed): heating curve -25 C -> 80 C, +15 C -> 40 C, linear ----
Tset=lambda t:80+(40-80)/(15-(-25))*(t-(-25))
assert Tset(-25)==80 and Tset(15)==40 and Tset(-10)==65 and Tset(-5)==60 and Tset(0)==55 and Tset(12)==43 and Tset(13)==42
assert (40-80)/(15+25)==-1.0
assert (55-40)/(80-40)==0.375 and 0.25*80+0.75*40==50 and 0.5*80+0.5*40==60
assert 2*5==10 and 2*5*10/20==5 and 2*5/20==0.5 and 10+5==15
assert round(5000/3600*4.19*20)==116 and round(5000/3600*4.19*10)==58

