    o=L(50,190,320,190)+L(50,20,50,190)+f'<line x1="{X(-25)}" y1="{Y(80)}" x2="{X(15)}" y2="{Y(40)}" class="lna"/>'
    o+=L(50,Y(65),X(-10),Y(65),'ln dash')+L(X(-10),Y(65),X(-10),190,'ln dash')+C(X(-10),Y(65),4,'hda')
    for v in (40,65,80):o+=TR(46,Y(v)+4,str(v),'t-s')
    for t in (-25,-10,0,15):o+=T(X(t),205,str(t),'t-s')
    o+=TL(58,26,'Т беру, °C (мақсат)','t-s t-b')+TL(200,220,'Т сыртқы, °C','t-s t-b')+TL(X(-10)+8,Y(65)-6,'−10 °C → 65 °C','t-s ac')
    return S(340,228,o,'Ауа райына тәуелді температуралық график')
